function ws_month(int $m){$a=[1=>'มกราคม',2=>'กุมภาพันธ์',3=>'มีนาคม',4=>'เมษายน',5=>'พฤษภาคม',6=>'มิถุนายน',7=>'กรกฎาคม',8=>'สิงหาคม',9=>'กันยายน',10=>'ตุลาคม',11=>'พฤศจิกายน',12=>'ธันวาคม'];return $a[$m]??'';}
function ws_end_ts(string $date,string $start,string $end){$st=strtotime($date.' '.$start);$et=strtotime($date.' '.$end);if($st===false||$et===false)return false;if($et<=$st)$et=strtotime('+1 day',$et);return $et;}
function ws_late(string $in,string $date,string $start,int $grace){$a=strtotime($in);$b=strtotime($date.' '.$start);if($a===false||$b===false)return 0;return max(0,(int)floor(($a-($b+$grace*60))/60));}
function ws_attendance_span(array $rows): array {
    $first=null;$last=null;$branchId=null;
    foreach($rows as $a){
        $in=!empty($a['check_in'])?strtotime((string)$a['check_in']):false;
        if($in!==false&&($first===null||$in<$first))$first=$in;
        $out=!empty($a['check_out'])?strtotime((string)$a['check_out']):false;
        if($out!==false&&($last===null||$out>$last))$last=$out;
        if($branchId===null&&!empty($a['branch_id']))$branchId=(int)$a['branch_id'];
    }
    $start=$first!==null?date('H:i',$first):'';$end=$last!==null?date('H:i',$last):'';
    $label=$start!==''?'IN '.$start.($end!==''?' · OUT '.$end:' · ยังไม่ Check-out'):'มีข้อมูล Attendance';
    return ['start'=>$start,'end'=>$end,'time_label'=>$label,'branch_id'=>$branchId];
}

function ws_employee_state(array $attendance,array $leaves,array $shifts,string $date,int $grace,string $today): array {
    $approved=false;$pending=false;
    foreach($leaves as $l){if(($l['status']??'')==='approved')$approved=true;if(($l['status']??'')==='pending')$pending=true;}
    if($attendance){if(!$shifts)return ['unscheduled',0];$late=0;$start=(string)($shifts[0]['start']??'18:00');foreach($attendance as $a)$late=max($late,ws_late((string)$a['check_in'],$date,$start,$grace));return [$late>0?'late':'worked',$late];}
    if($approved)return ['leave',0];if($pending)return ['leave_pending',0];
    if($shifts){$past=$date<$today;if($date===$today){foreach($shifts as $s){$et=ws_end_ts($date,(string)($s['start']??'18:00'),(string)($s['end']??'02:00'));if($et!==false&&time()>$et){$past=true;break;}}}return [$past?'absent':'scheduled',0];}
    return ['none',0];
}
