<?php if($canManage):?><section class="shift-editor v19-editor" id="newShiftCard" hidden><div class="v19-editor-head"><div><small>SHIFT EDITOR</small><h3>เพิ่มกะให้ <?=h((string)$emp['name'])?></h3><p>วันที่ <?=h(date('d/m/Y',strtotime($date)))?> · Auto-fill เวลาเปิด/ปิดร้านและสาขาประจำ</p></div><button type="button" class="v19-close-editor" data-close-shift-editor>×</button></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_shift"><input type="hidden" name="shift_id" value="0"><input type="hidden" name="employee_id" value="<?=$employeeId?>"><input type="hidden" name="date" value="<?=h($date)?>"><div class="form-grid v19-form-grid"><label>เริ่ม<input type="time" name="start" value="<?=h($defaultStart)?>" required></label><label>จบ<input type="time" name="end" value="<?=h($defaultEnd)?>" required></label><label>ประเภท<select name="type"><option value="regular">Regular</option><option value="half">Half Shift</option><option value="event">Event</option><option value="standby">Standby</option></select></label><label>สาขา<select name="branch_id"><option value="0">AUTO / Nearest</option><?php foreach($branches as $b):?><option value="<?=(int)$b['id']?>" <?=$defaultBranch===(int)$b['id']?'selected':''?>><?=h((string)$b['code'].' · '.(string)$b['name'])?></option><?php endforeach;?></select></label><label class="full">หมายเหตุ<input name="note" maxlength="200" placeholder="เช่น Event / VIP / Standby"></label></div><button class="primary full-btn">บันทึกกะ →</button></form></section><?php endif;?>
<section class="calendar-panel v19-calendar"><div class="month-head v19-month-head"><a href="?employee_id=<?=$employeeId?>&month=<?=$prev?>&date=<?=$prev?>-01">‹</a><div><small>MONTH VIEW · TEAM OVERVIEW</small><h2><?=h(ws_month($mon))?> <em><?=$year+543?></em></h2></div><div class="month-actions"><a class="today-link" href="?employee_id=<?=$employeeId?>&month=<?=h(substr($today,0,7))?>&date=<?=h($today)?>">วันนี้</a><a href="?employee_id=<?=$employeeId?>&month=<?=$next?>&date=<?=$next?>-01">›</a></div></div><div class="week-row"><?php foreach(['อา','จ','อ','พ','พฤ','ศ','ส'] as $i=>$w):?><span class="<?=$i===0?'sun':($i===6?'sat':'')?>"><?=$w?></span><?php endforeach;?></div><div class="calendar-grid v19-calendar-grid"><?php for($i=0;$i<$first;$i++):?><div class="day blank"></div><?php endfor;?><?php for($day=1;$day<=$days;$day++):$dt=sprintf('%04d-%02d-%02d',$year,$mon,$day);$m=$focusMeta[$dt];$td=$teamData[$dt];$people=[];foreach($td['rows'] as $row){$eid=(int)$row['employee_id'];if(!isset($people[$eid]))$people[$eid]=$row;}?><a href="?employee_id=<?=$employeeId?>&month=<?=$month?>&date=<?=$dt?>" class="day v19-day <?=$dt===$date?'selected':''?> <?=$dt===$today?'today':''?>" data-date="<?=h($dt)?>" data-focus-status="<?=h((string)$m['status'])?>"><div class="v19-day-head"><span class="date-num"><?=$day?></span><?php if($m['status']!=='none'):?><span class="focus-state <?=h((string)$m['status'])?>" title="<?=h((string)$emp['name'].' · '.ws_status((string)$m['status']))?>">●</span><?php endif;?></div><div class="team-bands"><?php foreach(['morning','day','evening','night'] as $band):$cnt=(int)($td['bands'][$band]??0);if(!$cnt)continue;?><span class="team-band <?=$band?>"><?=h(workforce_shift_band_label($band))?> <?=$cnt?></span><?php endforeach;?><?php if(!empty($td['unscheduled'])):?><span class="team-band walkin">นอกกะ <?=h((string)$td['unscheduled'])?></span><?php endif;?><?php if(!empty($td['leave'])):?><span class="team-band leave">ลา <?=h((string)$td['leave'])