<section class="v19-selected-manage"><div class="v19-section-head"><div><small>FOCUS EMPLOYEE · SELECTED DATE</small><h2><?=h((string)$emp['name'])?> · <?=h(date('d/m/Y',strtotime($date)))?></h2></div><button type="button" class="secondary" data-open-team-day>ดูรายชื่อทีมวันนี้</button></div><?php if(!$selShifts&&$selAtt):?><div class="v1271-unscheduled-note"><b>⚡ ตรวจพบการเข้างานนอกกะ</b><span>พนักงานมี Check-in จริง แต่ยังไม่มี Shift ในวันที่เลือก · Attendance ถูกเก็บตามจริงและไม่ถูกนับเป็นสาย หากต้องการจัดกะย้อนหลังสามารถกด “เพิ่มกะ” ด้านบนได้</span></div><?php endif;?><div class="v19-manage-grid"><section class="day-section"><div class="section-title"><h3>กะของพนักงานที่เลือก</h3><span><?=count($selShifts)?> กะ</span></div><?php if(!$selShifts):?><div class="empty">ยังไม่มีกะในวันนี้</div><?php endif;?><?php foreach($selShifts as $s):?><article class="shift-card"><div class="shift-summary"><div><small><?=h(ws_type((string)$s['type']))?></small><b><?=h((string)$s['start'].' – '.(string)$s['end'])?></b><span><?=h(ws_branch_name($d,$s['branch_id']??null))?></span><?php if(!empty($s['note'])):?><em><?=h((string)$s['note'])?></em><?php endif;?></div><button type="button" data-toggle-shift>แก้ไข ▾</button></div><?php if($canManage):?><div class="shift-detail" hidden><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_shift"><input type="hidden" name="shift_id" value="<?=(int)$s['id']?>"><input type="hidden" name="employee_id" value="<?=$employeeId?>"><input type="hidden" name="date" value="<?=h($date)?>"><div class="form-grid"><label>เริ่ม<input type="time" name="start" value="<?=h((string)$s['start'])?>"></label><label>จบ<input type="time" name="end" value="<?=h((string)$s['end'])?>"></label><label>ประเภท<select name="type"><?php foreach(['regular','half','event','standby'] as $tp):?><option value="<?=$tp?>" <?=$s['type']===$tp?'selected':''?>><?=h(ws_type($tp))?></option><?php endforeach;?>