<?php endforeach;?></section><?php endif;?><?php if($selLeaves):?><section class="day-section"><div class="section-title"><h3>Leave</h3><span><?=count($selLeaves)?></span></div><?php foreach($selLeaves as $l):?><article class="leave-card"><b><?=h((string)$l['type'])?></b><span><?=h((string)$l['reason'])?></span><em><?=h(strtoupper((string)$l['status']))?></em></article><?php endforeach;?></section><?php endif;?></div></section>
